UPDATE t_registration_mail_delivery_outbox
SET status = 'PROCESSING', claimed_until = #{claimedUntil}, updated_at = #{now}
WHERE verification_id = #{verificationId}
  AND ((status = 'PENDING' AND available_at <= #{now})
    OR (status = 'PROCESSING' AND claimed_until <= #{now}))

UPDATE t_registration_mail_delivery_outbox
SET status = 'SENT', claimed_until = NULL, last_error_code = NULL, updated_at = #{now}
WHERE verification_id = #{verificationId} AND status = 'PROCESSING' AND claimed_until = #{claimedUntil}

UPDATE t_registration_mail_delivery_outbox
SET status = #{status}, attempt_count = #{attemptCount}, available_at = #{availableAt},
    claimed_until = NULL, last_error_code = #{errorCode}, updated_at = #{now}
WHERE verification_id = #{verificationId} AND status = 'PROCESSING' AND claimed_until = #{claimedUntil}
